/// Negate a double-double.
#[inline]
fn neg(v: DoubleDouble) -> DoubleDouble {
    DoubleDouble {
        high: -v.high,
        low: -v.low,
    }
}

/// Payne–Hanek argument reduction for `|x| ≥ 2²⁰`.
///
/// Returns `(q, r)` with `q` the quadrant (low bits of `round(x·2/π)`) and `r ∈
/// [-π/4, π/4]` a double-double.  Multiplies the 53-bit significand by a 256-bit
/// window of 2/π selected by the exponent, reads off the integer part (for `q`)
/// and a 128-bit signed fraction, and scales the fraction by π/2.
#[inline]
fn payne_hanek(x: f64) -> (i64, DoubleDouble) {
    let bits = x.to_bits();
    let e = ((bits >> super::EXP_SHIFT) & 0x7ff) as i64; // biased exponent
    let sig = u128::from((bits & 0x000F_FFFF_FFFF_FFFF) | 0x0010_0000_0000_0000);

    // x = sig · 2ᵐ with m = e − 1023 − 52.  The 2/π bit aligning to 2⁰ of x·2/π is
    // index k = m; pick the 256-bit window starting two bits above that.
    let m = e - 1075;
    let w0 = (((m - 2).max(0)) / 64) as usize;

    let word = |i: usize| u128::from(*FRAC_2_PI.get(w0 + i).unwrap_or(&0));
    let (wa, wb, wc, wd) = (word(0), word(1), word(2), word(3));

    // P = sig · (wa·2¹⁹² + wb·2¹²⁸ + wc·2⁶⁴ + wd), as five 64-bit limbs.
    let (pa, pb, pc, pd) = (sig * wa, sig * wb, sig * wc, sig * wd);
    const MASK: u128 = 0xFFFF_FFFF_FFFF_FFFF;
    let p0 = pd as u64;
    let c = (pd >> 64) + (pc & MASK);
    let p1 = c as u64;
    let c = (c >> 64) + (pc >> 64) + (pb & MASK);
    let p2 = c as u64;
    let c = (c >> 64) + (pb >> 64) + (pa & MASK);
    let p3 = c as u64;
    let p4 = ((c >> 64) + (pa >> 64)) as u64;
    let p = [p0, p1, p2, p3, p4];

    // Units bit of x·2/π is at P bit `b = 256 + 64·w0 − m`.
    let b = 256 + 64 * w0 as i64 - m;
    let bit_at = |start: i64| -> u64 {
        let w = (start / 64) as usize;
        let o = (start % 64) as u32;
        let lo = p.get(w).copied().unwrap_or(0);
        let hi = p.get(w + 1).copied().unwrap_or(0);
        if o == 0 {
            lo
        } else {
            (lo >> o) | (hi << (64 - o))
        }
    };

    // 192-bit window [b−128, b+63]: top 64 bits are the integer part (quadrant),
    // low 128 bits are the signed fraction of x·2/π.
    let frac = (u128::from(bit_at(b - 64)) << 64) | u128::from(bit_at(b - 128));
    let q = bit_at(b) as i64;
    let frac = frac as i128;

    // round-to-nearest: a negative signed fraction means the integer rounded up.
    let quadrant = q.wrapping_sub((frac >> 127) as i64);

    // r = (frac / 2¹²⁸) · π/2 ∈ [-π/4, π/4], as a double-double.
    let hi = frac as f64;
    let lo = (frac - hi as i128) as f64;
    let scale = crate::exp2i(-128);
    let r = DoubleDouble {
        high: hi * scale,
        low: lo * scale,
    } * PIO2;

    (quadrant, r)
}

/// Argument reduction: `x ≥ 0` finite → `(quadrant, r)` with `r ∈ [-π/4, π/4]`.
#[inline]
fn rem_pio2(x: f64) -> (i64, DoubleDouble) {
    // Medium range: Cody–Waite with the 3-word π/2 (q small enough that q·PIO2_1,
    // q·PIO2_2 are exact).  Handles `q = 0` (no reduction) too.
    if x < 1_048_576.0 {
        let q = (x * FRAC_2_PI_F64).round_ties_even();
        let p3 = q * PIO2_3;
        // ((x − q·PIO2_1) − q·PIO2_2) keeping residuals exactly (2Sum).
        let a = DoubleDouble::from_sum(x, q * -PIO2_1);
        let b = DoubleDouble::from_sum(a.high, q * -PIO2_2);
        let lo = (a.low + b.low) - p3;
        // SAFETY: |q| < 2²⁰.
        return (unsafe { q.to_int_unchecked() }, fast_sum(b.high, lo));
    }

    payne_hanek(x)
}

/// `sin(r)` for `r ∈ [-π/4, π/4]` as a double-double, by full double-double
/// Horner of [`SIN_KERNEL`] (≈2⁻¹²⁷) — the accurate `sin` half.
#[inline]
fn sin_kernel(r: DoubleDouble) -> DoubleDouble {
    r * poly_dd(r * r, &SIN_KERNEL)
}

/// `cos(r)` for `r ∈ [-π/4, π/4]` as a double-double, by full double-double
/// Horner of [`COS_KERNEL`] (≈2⁻¹²²) — the accurate `cos` half.
#[inline]
fn cos_kernel(r: DoubleDouble) -> DoubleDouble {
    poly_dd(r * r, &COS_KERNEL)
}

/// `(sin(r), cos(r))` for `r ∈ [-π/4, π/4]`, both as double-doubles — the
/// accurate kernel behind [`sin_cos_kernel_fast`], used by `sincos`/`tan`.
#[inline]
fn sin_cos_kernel(r: DoubleDouble) -> (DoubleDouble, DoubleDouble) {
    let u = r * r;
    (r * poly_dd(u, &SIN_KERNEL), poly_dd(u, &COS_KERNEL))
}

/// The squares shared by the fast sin/cos parts: `uu = r²`, `u2 = uu²`, and
/// `u3 = uu.high³`.
#[inline]
fn fast_squares(r: DoubleDouble) -> (DoubleDouble, DoubleDouble, f64) {
    let uu = r * r;
    let u = uu.high;
    (uu, uu * uu, u * u * u)
}

/// `sin(r)` from the precomputed squares — the `sin` half of the fast path.
///
/// Peels the three exact leading terms of `sin(r)/r` into double-double and
/// evaluates only the tiny `u³` tail ([`SIN_TAIL`]) in plain `f64`, so the result
/// comes out to ≈2⁻⁶⁰ for a fraction of [`sin_kernel`]'s cost.
#[inline]
fn sin_part_fast(r: DoubleDouble, uu: DoubleDouble, u2: DoubleDouble, u3: f64) -> DoubleDouble {
    // sin(r)/r = 1 − u/6 + u²/120 + u³·SIN_TAIL(u)
    let sin_lead = ONE + uu / -6.0 + u2 * FRAC_1_120;
    let sin_over_r = sin_lead
        + DoubleDouble {
            high: u3 * crate::poly(uu.high, &SIN_TAIL),
            low: 0.0,
        };
    r * sin_over_r
}

/// `cos(r)` from the precomputed squares — the `cos` half of the fast path.  See
/// [`sin_part_fast`]; the `u³` tail is [`COS_TAIL`].
#[inline]
fn cos_part_fast(uu: DoubleDouble, u2: DoubleDouble, u3: f64) -> DoubleDouble {
    // cos(r) = 1 − u/2 + u²/24 + u³·COS_TAIL(u)
    let cos_lead = ONE + uu * -0.5 + u2 * FRAC_1_24;
    cos_lead
        + DoubleDouble {
            high: u3 * crate::poly(uu.high, &COS_TAIL),
            low: 0.0,
        }
}

/// `sin(r)` for `r ∈ [-π/4, π/4]`, the fast path — only the `sin` half.
#[inline]
fn sin_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let (uu, u2, u3) = fast_squares(r);
    sin_part_fast(r, uu, u2, u3)
}

/// `cos(r)` for `r ∈ [-π/4, π/4]`, the fast path — only the `cos` half.
#[inline]
fn cos_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let (uu, u2, u3) = fast_squares(r);
    cos_part_fast(uu, u2, u3)
}

/// Lean counterpart of [`sin_cos_kernel`] computing both halves, for `sincos`.
#[inline]
fn sin_cos_kernel_fast(r: DoubleDouble) -> (DoubleDouble, DoubleDouble) {
    let (uu, u2, u3) = fast_squares(r);
    (sin_part_fast(r, uu, u2, u3), cos_part_fast(uu, u2, u3))
}

/// `tan(r)` for `r ∈ [−π/4, π/4]`, as a double-double, via the direct series
/// `tan(r) = r·T(r²)`.  The 6 leading terms of `T` are carried in double-double
/// ([`TAN_LEADS`], 2-way Estrin) and the `v⁶` remainder ([`TAN_TAIL`]) in plain
/// `f64`.  One kernel — versus the sin/cos pair plus a reciprocal — feeds [`tan`].
#[inline]
fn tan_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let w = r * r; // v = r²
    let v = w.high;
    let v2 = v * v;
    let v6 = v2 * v2 * v2;
    let w2 = w * w;
    let p0 = TAN_LEADS[0] + w * TAN_LEADS[1];
    let p1 = TAN_LEADS[2] + w * TAN_LEADS[3];
    let p2 = TAN_LEADS[4] + w * TAN_LEADS[5];
    let t = (p0 + w2 * (p1 + w2 * p2))
        + DoubleDouble {
            high: v6 * crate::poly(v, &TAN_TAIL),
            low: 0.0,
        };
    r * t
}

/// Reconstruct `sin(|x|)` from the kernel pair and quadrant `q` (before the sign
/// of `x` is restored).  Shared by the fast and accurate paths so they select
/// identically.
#[inline]
fn select_sin(q: i64, s: DoubleDouble, c: DoubleDouble) -> DoubleDouble {
    let v = if q & 1 == 0 { s } else { c };
    if q & 2 == 0 { v } else { neg(v) }
}

/// Reconstruct `cos(|x|)` from the kernel pair and quadrant `q`.
#[inline]
fn select_cos(q: i64, s: DoubleDouble, c: DoubleDouble) -> DoubleDouble {
    let v = if q & 1 == 0 { c } else { s };
    if q.wrapping_add(1) & 2 == 0 {
        v
    } else {
        neg(v)
    }
}

/// Ziv gate: round `v` to `f64` when both ends of its `±TRIG_ZIV_EPS` (relative)
/// error interval agree, else `None` to fall back to the accurate kernel.
#[inline]
fn ziv(v: DoubleDouble) -> Option<f64> {
    let eps = v.high.abs() * TRIG_ZIV_EPS;
    let lo = v.high + (v.low - eps);
    let hi = v.high + (v.low + eps);
    (lo == hi).then_some(lo)
}

/// π as a double-double, for `sin(πx)` (the lgamma reflection).
const PI_DD: DoubleDouble = DoubleDouble {
    high: 3.141_592_653_589_793,
    low: 1.224_646_799_147_353_2e-16,
};

/// `sin(πx)` as a double-double for `|x| < 2⁵²`, where `x − q/2` is exact
///
/// Reduces `x = q/2 + r`, `r ∈ [−¼, ¼]`, and selects `±sin(πr)`/`±cos(πr)` by
/// `q mod 4`, with `πr ∈ [−π/4, π/4]` carried as a double-double into the
/// trigonometric kernels.
#[inline]
fn sinpi_dd(x: f64) -> DoubleDouble {
    let q = (2.0 * x).round_ties_even();
    let theta = PI_DD * (x - q * 0.5);
    // SAFETY: `|x| < 2⁵²`, so `|q| < 2⁵³` fits an `i64`.
    match unsafe { q.to_int_unchecked::<i64>() } & 3 {
        0 => sin_kernel(theta),
        1 => cos_kernel(theta),
        2 => neg(sin_kernel(theta)),
        _ => neg(cos_kernel(theta)),
    }
}

/// `|sin(πx)|` as a double-double for `|x| < 2⁵²` (see [`sinpi_dd`])
///
/// The lgamma reflection needs `ln|sin(πz)|` accurate even as `z` nears an
/// integer; there `|sin(πz)| ≈ π·|r|` with `r = z − round(z)` exact, so the
/// kernel's leading term keeps full relative accuracy.
#[inline]
pub(super) fn abs_sinpi_dd(x: f64) -> DoubleDouble {
    let v = sinpi_dd(x);
    if v.high < 0.0 { neg(v) } else { v }
}

/// Sine
#[must_use]
#[inline]
pub fn sin(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: sin(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // sin(|x|): even quadrants use sin(r), odd use cos(r); q&2 sets the sign.
    // Only the selected half is computed (vs. both for `sincos`).
    let need_cos = q & 1 != 0;
    let negate = q & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_cos {
        cos_kernel_fast(r)
    } else {
        sin_kernel_fast(r)
    });
    let magnitude = ziv(fast).unwrap_or_else(|| {
        let v = signed(if need_cos {
            cos_kernel(r)
        } else {
            sin_kernel(r)
        });
        v.high + v.low
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}

/// Cosine
#[must_use]
#[inline]
pub fn cos(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: cos(x) = 1 to within ½ ulp.
    if x.abs() < SMALL {
        return 1.0;
    }

    let (q, r) = rem_pio2(x.abs());

    // cos(|x|): even quadrants use cos(r), odd use sin(r); (q+1)&2 sets the sign.
    let need_sin = q & 1 != 0;
    let negate = q.wrapping_add(1) & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_sin {
        sin_kernel_fast(r)
    } else {
        cos_kernel_fast(r)
    });
    ziv(fast).unwrap_or_else(|| {
        let v = signed(if need_sin {
            sin_kernel(r)
        } else {
            cos_kernel(r)
        });
        v.high + v.low
    })
}

/// Simultaneous sine and cosine
#[must_use]
#[inline]
pub fn sincos(x: f64) -> (f64, f64) {
    if !x.is_finite() {
        return (f64::NAN, f64::NAN);
    }

    // |x| < 2⁻²⁷: (sin, cos) = (x, 1) to within ½ ulp; preserves ±0 in sin.
    if x.abs() < SMALL {
        return (x, 1.0);
    }

    let (q, r) = rem_pio2(x.abs());

    let (s, c) = sin_cos_kernel_fast(r);
    // Both components must pass the gate; otherwise recompute both accurately.
    let (sin, cos) = match (ziv(select_sin(q, s, c)), ziv(select_cos(q, s, c))) {
        (Some(sin), Some(cos)) => (sin, cos),
        _ => {
            let (s, c) = sin_cos_kernel(r);
            let sin_v = select_sin(q, s, c);
            let cos_v = select_cos(q, s, c);
            (sin_v.high + sin_v.low, cos_v.high + cos_v.low)
        }
    };

    let sin = if x.is_sign_negative() { -sin } else { sin };
    (sin, cos)
}

/// Tangent
#[must_use]
#[inline]
pub fn tan(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: tan(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // tan has period π, so tan(|x|) = tan(r) for even quadrants and −cot(r) =
    // −1/tan(r) for odd ones — one kernel, a reciprocal only half the time.
    let t = tan_kernel_fast(r);
    let fast = if q & 1 == 0 { t } else { neg(t.recip()) };
    let magnitude = ziv(fast).unwrap_or_else(|| {
        // Accurate fallback: the sin/cos pair ratio (the correctly-rounded oracle).
        let (s, c) = sin_cos_kernel(r);
        let t = select_sin(q, s, c) * select_cos(q, s, c).recip();
        t.high + t.low
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}
